        for (uint32_t o = 0; o < 0x60; o += 4) { const uint32_t h = rd(C + o); std::fprintf(stderr, " +%X=%08X", o, h); if (ok(h, 0x40) && o >= 8) std::fprintf(stderr, "(vt %08X +8 %08X sz %X)", rd(h + 4u), rd(h + 8u), rd(h - 8u)); }
        std::fprintf(stderr, "\n");
