        static uint32_t lbs = 0; static std::vector<uint32_t> snap; static std::vector<int> cnt;
        const uint32_t N = 0x200u + 20u;
        auto addr = [&](uint32_t i) { return i < 0x200u ? MGR + 4u * i : g_bs + 0x754u + 4u * (i - 0x200u); };
