    if (!ao9_on() || !g_bs || !e.started || !ok(e.actor, 0x12D0) || !ok(e.slot_actor, 0x12D0) || !assist_off_now() || pad_driven(e.actor)) return;
    const uint32_t E = e.actor, M = e.slot_actor, k = ao9_slot_k(M); if (k > 1) return;
