            if (g_xbroken.count(a) && xbase(a) > 0 && xbrv(a) >= xbase(a)) { g_xbroken.erase(a); if (g_log) std::fprintf(stderr, "[TAGTEAM] t=%.2fs %s: break over (BRV back at %u)\n", dissidia_battle_age() / 60.0f, role_of(a), xbase(a)); }
