    std::fprintf(stderr, "[TTSP] row %d (char %d) CPU settings: strength %u, level %u (0 = Auto), type %u (0 = Random)\n", row + 1, g_sp.chars[row], g_sp.cfg[row][0], g_sp.cfg[row][1], g_sp.cfg[row][2]);
